"""assets.py -- Embedded static assets (logos, branding)."""
import base64
import tempfile
from pathlib import Path

COMAU_LOGO_B64 = """"""

def get_logo_path() -> Path:
    local = Path(__file__).parent.parent / "resources" / "Logo-COMAU.png"
    if local.exists():
        return local
    tmp = Path(tempfile.gettempdir()) / "SimSeq" / "Logo-COMAU.png"
    if not tmp.exists():
        tmp.parent.mkdir(parents=True, exist_ok=True)
        tmp.write_bytes(base64.b64decode(COMAU_LOGO_B64))
    return tmp
